    public void erroCupomNaoAplicavel() {
        List<Item> itens = Arrays.asList(
            new Item("Camiseta", new BigDecimal("100.00"), 1, new BigDecimal("0.30"))
        );

        ResumoResponse resposta = calculadora.calcular(
